	initMetrics()
	recordSelection("ok", ModeSelected, 10, 3, 1.5)
	recordFallback(SelectionOutcomeNoMatch)
	recordCallDenied("not_in_plan")
	store := NewSessionPlanStore()
	setPlansActive(store, 5)
	store.Stop()
}

